class Solution:
    def rotate(self, nums: List[int], k: int) -> None:
        k %= len(nums)
        def rev(i, j):
            while i < j:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1; j -= 1
        rev(0, len(nums)-1)
        rev(0, k-1)
        rev(k, len(nums)-1)

sort-colors:
class Solution:
    def sortColors(self, nums: List[int]) -> None:
        l, m, h = 0, 0, len(nums)-1
        while m <= h:
            if nums[m] == 0:
                nums[l], nums[m] = nums[m], nums[l]
                l += 1; m += 1
            elif nums[m] == 1:
                m += 1
            else:
                nums[m], nums[h] = nums[h], nums[m]
                h -= 1

find-peak-element:
class Solution:
    def findPeakElement(self, nums: List[int]) -> int:
        l, r = 0, len(nums)-1
        while l < r:
            m = (l+r)//2
            if nums[m] < nums[m+1]: l = m+1
            else: r = m
        return l

