class Solution:
    def findMin(self, nums: List[int]) -> int:
        l, r = 0, len(nums)-1
        while l < r:
            m = (l+r)//2
            if nums[m] > nums[r]: l = m+1
            else: r = m
        return nums[l]

single-number-ii:
class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        ones = twos = 0
        for x in nums:
            ones = (ones ^ x) & ~twos
            twos = (twos ^ x) & ~ones
        return ones

daily-temperatures:
class Solution:
    def dailyTemperatures(self, temperatures: List[int]) -> List[int]:
        res = [0]*len(temperatures)
        stack = []
        for i, t in enumerate(temperatures):
            while stack and temperatures[stack[-1]] < t:
                j = stack.pop()
                res[j] = i - j
            stack.append(i)
        return res

evaluate-reverse-polish-notation:
class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        st = []
        for t in tokens:
            if t in '+-*/':
                b = st.pop(); a = st.pop()
                if t == '+': st.append(a+b)
                elif t == '-': st.append(a-b)
                elif t == '*': st.append(a*b)
                else: st.append(int(a/b))
            else:
                st.append(int(t))
        return st[0]

online-stock-span:
class StockSpanner:
    def __init__(self):
        self.stack = []
    def next(self, price: int) -> int:
        span = 1
        while self.stack and self.stack[-1][0] <= price:
            span += self.stack.pop()[1]
        self.stack.append((price, span))
        return span

number-of-islands:
class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        R, C = len(grid), len(grid[0])
        def dfs(i, j):
            if i < 0 or j < 0 or i >= R or j >= C or grid[i][j] == '0': return
            grid[i][j] = '0'
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                dfs(i+di, j+dj)
        ans = 0
        for i in range(R):
            for j in range(C):
                if grid[i][j] == '1':
                    ans += 1
                    dfs(i, j)
        return ans

course-schedule:
class Solution:
    def canFinish(self, numCourses: int, prerequisites: List[List[int]]) -> bool:
        from collections import defaultdict, deque
        adj = defaultdict(list)
        indeg = [0]*numCourses
        for a, b in prerequisites:
            adj[b].append(a)
            indeg[a] += 1
        q = deque([i for i in range(numCourses) if indeg[i] == 0])
        count = 0
        while q:
            u = q.popleft()
            count += 1
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0: q.append(v)
        return count == numCourses

spiral-matrix:
class Solution:
    def spiralOrder(self, matrix: List[List[int]]) -> List[int]:
        res = []
        t, b, l, r = 0, len(matrix)-1, 0, len(matrix[0])-1
        while t <= b and l <= r:
            for c in range(l, r+1): res.append(matrix[t][c])
            t += 1
            for rr in range(t, b+1): res.append(matrix[rr][r])
            r -= 1
            if t <= b:
                for c in range(r, l-1, -1): res.append(matrix[b][c])
                b -= 1
            if l <= r:
                for rr in range(b, t-1, -1): res.append(matrix[rr][l])
                l += 1
        return res

set-matrix-zeroes:
class Solution:
    def setZeroes(self, matrix: List[List[int]]) -> None:
        rows, cols = set(), set()
        R, C = len(matrix), len(matrix[0])
        for i in range(R):
            for j in range(C):
                if matrix[i][j] == 0:
                    rows.add(i); cols.add(j)
        for i in range(R):
            for j in range(C):
                if i in rows or j in cols:
                    matrix[i][j] = 0

word-search:
class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        R, C = len(board), len(board[0])
        def dfs(i, j, k):
            if k == len(word): return True
            if i < 0 or j < 0 or i >= R or j >= C or board[i][j] != word[k]: return False
            tmp = board[i][j]
            board[i][j] = '#'
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                if dfs(i+di, j+dj, k+1): return True
            board[i][j] = tmp
            return False
        for i in range(R):
            for j in range(C):
                if dfs(i, j, 0): return True
        return False

maximum-swap:
class Solution:
    def maximumSwap(self, num: int) -> int:
        s = list(str(num))
        last = {int(c): i for i, c in enumerate(s)}
        for i, c in enumerate(s):
            for d in range(9, int(c), -1):
                if last.get(d, -1) > i:
                    s[i], s[last[d]] = s[last[d]], s[i]
                    return int(''.join(s))
        return num

sum-of-subarray-minimums:
class Solution:
    def sumSubarrayMins(self, arr: List[int]) -> int:
        MOD = 10**9+7
        n = len(arr)
        left = [-1]*n
        right = [n]*n
        stack = []
        for i in range(n):
            while stack and arr[stack[-1]] >= arr[i]: stack.pop()
            left[i] = stack[-1] if stack else -1
            stack.append(i)
        stack = []
        for i in range(n-1, -1, -1):
            while stack and arr[stack[-1]] > arr[i]: stack.pop()
            right[i] = stack[-1] if stack else n
            stack.append(i)
        ans = 0
        for i in range(n):
            ans = (ans + arr[i]*(i-left[i])*(right[i]-i)) % MOD
        return ans

out-of-boundary-paths:
class Solution:
    def findPaths(self, m: int, n: int, maxMove: int, startRow: int, startColumn: int) -> int:
        MOD = 10**9+7
        dp = [[0]*n for _ in range(m)]
        dp[startRow][startColumn] = 1
        ans = 0
        for _ in range(maxMove):
            ndp = [[0]*n for _ in range(m)]
            for i in range(m):
                for j in range(n):
                    if dp[i][j]:
                        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                            ni, nj = i+di, j+dj
                            if 0 <= ni < m and 0 <= nj < n:
                                ndp[ni][nj] = (ndp[ni][nj] + dp[i][j]) % MOD
                            else:
                                ans = (ans + dp[i][j]) % MOD
            dp = ndp
        return ans

